(() => {
  'use strict';
  const canvas = document.querySelector('#world');
  const ctx = canvas.getContext('2d');
  const mini = document.querySelector('#minimap');
  const mctx = mini.getContext('2d');
  const W = 3000, H = 2400, TILE = 64;
  const player = {x:1500,y:1190,r:13,hp:100,maxHp:100,mana:60,maxMana:60,level:1,xp:0,next:250,gold:35,potions:3,facing:0,walk:0,attack:0,invuln:0,dead:0};
  const npc = {x:1655,y:1165,name:'Mara, the Ashkeeper'};
  const colors = ['#253329','#29372c','#2b382d','#26342a','#303a2e','#29352c'];
  const keys = new Set(), enemies = [], particles = [], projectiles = [], decals = [];
  const cooldowns = {q:0,e:0,r:0,basic:0};
  let camera={x:0,y:0}, last=performance.now(), elapsed=0, selected=null, kills=0, soundOn=false, toastTimer=0, modalMode='';
  let audio;
  const hash=(x,y)=>{let n=Math.imul(x|0,374761393)+Math.imul(y|0,668265263)|0;n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967295};
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function seedEnemies(){
    const spots=[[1310,1050],[1590,990],[1800,1270],[1200,1380],[1930,1050],[1390,1540],[1700,1510],[1050,1120],[2030,1370]];
    spots.forEach((p,i)=>enemies.push({x:p[0],y:p[1],homeX:p[0],homeY:p[1],r:15,hp:52,maxHp:52,level:2+(i%3===0?1:0),speed:26+(i%3)*3,attack:0,hit:0,phase:hash(i,8)*6.28,alive:true,respawn:0,aggro:false,name:'Hollow Wraith'}));
  }
  seedEnemies();
  function resize(){const d=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;canvas.width=Math.floor(w*d);canvas.height=Math.floor(h*d);ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingEnabled=true;}
  addEventListener('resize',resize);resize();
  const screen=()=>({w:innerWidth,h:innerHeight});
  function worldToScreen(x,y){return{x:x-camera.x,y:y-camera.y}}
  function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
  function tone(freq=240,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audio ||= new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(_){}}
  function addParticle(x,y,color,count=8,power=70,size=3){for(let i=0;i<count;i++){const a=Math.random()*6.28,s=Math.random()*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-15,life:.35+Math.random()*.55,max:.9,color,size:size*(.5+Math.random())});}}
  function damagePlayer(amount){if(player.invuln>0||player.dead>0)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.22;addParticle(player.x,player.y,'#bb5550',4,35,2);tone(90,.12,'triangle',.05);if(player.hp<=0){player.dead=2.2;toast('You have fallen. The veil will return you...');}}
  function awardXP(amount){player.xp+=amount;while(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.round(player.next*1.35);player.maxHp+=18;player.maxMana+=10;player.hp=player.maxHp;player.mana=player.maxMana;toast(`LEVEL UP — You are now level ${player.level}`);tone(520,.3,'sine',.055);addParticle(player.x,player.y,'#e4cb86',32,130,4);}updateHUD();}
  function killEnemy(e){if(!e.alive)return;e.alive=false;e.respawn=18+Math.random()*10;e.aggro=false;selected=null;kills++;player.gold+=5+Math.floor(Math.random()*7);awardXP(55+e.level*8);addParticle(e.x,e.y,'#b36b6b',20,105,4);tone(155,.2,'sawtooth',.035);document.querySelector('#kills').textContent=Math.min(kills,5);document.querySelector('#gold').textContent='◈ '+player.gold;if(kills===5){toast('Quest complete — A debt in ash');awardXP(120);player.gold+=35;document.querySelector('#gold').textContent='◈ '+player.gold;document.querySelector('#quest-check').textContent='✓';document.querySelector('.quest-progress').style.borderColor='#b59b5570';}}
  function hitEnemy(e,damage,kind='melee'){if(!e.alive)return;e.hp-=damage;e.hit=.22;addParticle(e.x,e.y,kind==='magic'?'#9c8ce1':'#d99b76',kind==='nova'?12:6,kind==='nova'?95:55,3);tone(kind==='magic'?390:185,.07,kind==='magic'?'sine':'triangle',.025);selected=e;if(e.hp<=0)killEnemy(e);updateHUD();}
  function nearestEnemy(range=150){let best=null,bd=range;for(const e of enemies)if(e.alive){const d=dist(player,e);if(d<bd){bd=d;best=e;}}return best;}
  function attack(target=selected){if(cooldowns.basic>0)return;const e=target&&target.alive?target:nearestEnemy(100);if(!e){toast('No enemy in range');return;}const d=dist(player,e);if(d>130){selected=e;toast('Move closer to strike');return;}selected=e;player.facing=Math.atan2(e.y-player.y,e.x-player.x);player.attack=.24;cooldowns.basic=.45;hitEnemy(e,20+player.level*3);}
  function cast(which){const cd=cooldowns[which];if(cd>0){toast('Ability is not ready');return;}if(which==='q'){
      if(player.mana<12){toast('Not enough mana');return;}const e=selected&&selected.alive?selected:nearestEnemy(350);if(!e){toast('No target in sight');return;}player.mana-=12;cooldowns.q=3.5;projectiles.push({x:player.x,y:player.y-8,target:e,speed:390,damage:34+player.level*5,color:'#b9a0ff'});addParticle(player.x,player.y,'#a892e6',8,40,3);tone(510,.14,'sine');
    }else if(which==='e'){
      if(player.mana<16){toast('Not enough mana');return;}player.mana-=16;cooldowns.e=8;let e=selected&&selected.alive?selected:nearestEnemy(240);let dx=e?e.x-player.x:Math.cos(player.facing)*100,dy=e?e.y-player.y:Math.sin(player.facing)*100,n=Math.hypot(dx,dy)||1;const ox=player.x,oy=player.y;player.x=clamp(player.x+dx/n*100,35,W-35);player.y=clamp(player.y+dy/n*100,35,H-35);addParticle(ox,oy,'#9b8edb',14,100,4);addParticle(player.x,player.y,'#d7c6ff',18,100,4);for(const mob of enemies)if(mob.alive&&dist(player,mob)<63)hitEnemy(mob,22+player.level*3,'magic');tone(720,.17,'sine');
    }else if(which==='r'){
      if(player.mana<28){toast('Not enough mana');return;}player.mana-=28;cooldowns.r=18;addParticle(player.x,player.y,'#b898e8',46,145,5);for(const e of enemies)if(e.alive&&dist(player,e)<185)hitEnemy(e,48+player.level*6,'nova');tone(250,.4,'sawtooth',.045);
    }updateHUD();}
  function usePotion(){if(player.potions<=0){toast('No healing draughts left');return;}if(player.hp>=player.maxHp){toast('Your health is already full');return;}player.potions--;player.hp=Math.min(player.maxHp,player.hp+48);addParticle(player.x,player.y,'#e66c64',18,90,4);toast('Healing draught · restored vitality');document.querySelector('#potion i').textContent=player.potions;updateHUD();tone(620,.2,'sine');}
  function updateHUD(){document.querySelector('#health-fill').style.width=`${100*player.hp/player.maxHp}%`;document.querySelector('#health-text').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;document.querySelector('#mana-fill').style.width=`${100*player.mana/player.maxMana}%`;document.querySelector('#mana-text').textContent=`${Math.floor(player.mana)} / ${player.maxMana}`;document.querySelector('#xp-fill').style.width=`${100*player.xp/player.next}%`;document.querySelector('#xp-num').textContent=player.xp;document.querySelector('#xp-next').textContent=player.next;document.querySelector('#level').textContent=String(player.level).padStart(2,'0');document.querySelector('#level-top').textContent=String(player.level).padStart(2,'0');document.querySelector('#power').textContent=18+(player.level-1)*5;document.querySelector('#target-bar').classList.toggle('visible',!!selected?.alive);if(selected?.alive){document.querySelector('#target-health').style.width=`${Math.max(0,selected.hp/selected.maxHp*100)}%`;document.querySelector('#target-level').textContent=`LV. ${selected.level}`;}}
  function interact(){if(dist(player,npc)<95){openModal('dialog');return;}toast('Nothing to interact with nearby');}
  function openModal(mode){modalMode=mode;const backdrop=document.querySelector('#modal-backdrop'),content=document.querySelector('#modal-content');backdrop.classList.add('open');if(mode==='character'){content.innerHTML=`<div class="subhead">CHARACTER · NIGHTWARDEN</div><h2>The Wanderer</h2><p>A keeper of the last ember, bound to walk where the veil grows thin.</p><div class="stat-grid"><div class="stat"><small>LEVEL</small><b>${player.level}</b></div><div class="stat"><small>POWER</small><b>${18+(player.level-1)*5}</b></div><div class="stat"><small>VITALITY</small><b>${player.maxHp}</b></div><div class="stat"><small>WILL</small><b>${player.maxMana}</b></div></div>`;}else if(mode==='inventory'){content.innerHTML=`<div class="subhead">YOUR BELONGINGS</div><h2>Inventory</h2><p>What remains after the old world burned.</p><div class="inventory-grid"><div class="inventory-cell filled" title="Ashen draught">⚗<small>${player.potions}</small></div><div class="inventory-cell filled" title="Worn iron sword">⚔</div><div class="inventory-cell filled" title="Veil-woven mantle">♜</div><div class="inventory-cell">◇</div><div class="inventory-cell">◇</div>${Array.from({length:10},()=>'<div class="inventory-cell"></div>').join('')}</div>`;}else if(mode==='map'){content.innerHTML=`<div class="map-modal"><div class="subhead">VEILFALL · REGION MAP</div><h2>The Weeping Fen</h2><canvas id="bigmap" width="720" height="430"></canvas><p>Old causeways cross the fen. Red marks are hostile wraiths; the pale star is your position.</p></div>`;drawMap(document.querySelector('#bigmap').getContext('2d'),720,430,true);}else{content.innerHTML=`<div class="subhead">A LONE LIGHT IN THE FEN</div><h2>Mara, the Ashkeeper</h2><p>“Listen to the stones, little flame. They remember the names we have forgotten. The wraiths rise when the old bells ring below the mud.”</p><p>She presses a small glass vial into your hand. <em style="color:#d5b66e">“For the road. You will need it.”</em></p><button class="dialog-reward" id="take-gift">Accept the draught <span>⚗</span></button>`;document.querySelector('#take-gift').onclick=()=>{player.potions++;document.querySelector('#potion i').textContent=player.potions;closeModal();toast('Received an Ashen draught');};}}
  function closeModal(){document.querySelector('#modal-backdrop').classList.remove('open');modalMode='';}
  document.querySelector('#modal-close').onclick=closeModal;document.querySelector('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});
  document.querySelector('#inventory-btn').onclick=()=>openModal('inventory');document.querySelector('#character-btn').onclick=()=>openModal('character');document.querySelector('#map-btn').onclick=()=>openModal('map');document.querySelector('#basic').onclick=()=>attack();document.querySelector('#potion').onclick=usePotion;document.querySelector('#skill-q').onclick=()=>cast('q');document.querySelector('#skill-e').onclick=()=>cast('e');document.querySelector('#skill-r').onclick=()=>cast('r');document.querySelector('#sound-btn').onclick=()=>{soundOn=!soundOn;document.querySelector('#sound-btn').style.color=soundOn?'#e1c27d':'';toast(soundOn?'Sound enabled':'Sound muted');if(soundOn)tone(440,.1);};
  const form=document.querySelector('#chat-form');form.addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#chat-input'),text=input.value.trim();if(text){const p=document.createElement('p');p.innerHTML=`<b style="color:#d2bd8c">[LOCAL]</b> <span>${text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</span>`;document.querySelector('#chat-lines').append(p);input.value='';}});
  document.querySelectorAll('.chat-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chat-tabs button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');});
  addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k===' ')attack();if(k==='q'||k==='e'||k==='r')cast(k);if(k==='h')usePotion();if(k==='f')interact();if(k==='i')openModal('inventory');if(k==='c')openModal('character');if(k==='m')openModal('map');if(k==='escape')closeModal();});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());
  document.querySelectorAll('[data-dir]').forEach(b=>{const key={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key);b.setPointerCapture(e.pointerId);});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(key)));});document.querySelector('#touch-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack();});
  canvas.addEventListener('pointerdown',e=>{if(e.target!==canvas)return;const wx=e.clientX+camera.x,wy=e.clientY+camera.y;let closest=null,bd=42;for(const mob of enemies)if(mob.alive){const d=Math.hypot(mob.x-wx,mob.y-wy);if(d<bd){bd=d;closest=mob;}}if(closest){selected=closest;updateHUD();if(e.detail>1)attack(closest);}else if(e.button===0&&innerWidth>800&&e.clientY<innerHeight-180){const dx=wx-player.x,dy=wy-player.y,n=Math.hypot(dx,dy);if(n>18){player.facing=Math.atan2(dy,dx);const goalX=clamp(wx,30,W-30),goalY=clamp(wy,30,H-30);player.moveGoal={x:goalX,y:goalY};}}});
  function drawTerrain(w,h){ctx.fillStyle='#26332a';ctx.fillRect(0,0,w,h);const x0=Math.floor(camera.x/TILE)-1,y0=Math.floor(camera.y/TILE)-1,x1=Math.ceil((camera.x+w)/TILE)+1,y1=Math.ceil((camera.y+h)/TILE)+1;for(let ty=y0;ty<=y1;ty++)for(let tx=x0;tx<=x1;tx++){if(tx<0||ty<0||tx*TILE>W||ty*TILE>H)continue;const wx=tx*TILE,wy=ty*TILE,s=hash(tx,ty),sx=wx-camera.x,sy=wy-camera.y;const pathX=W*.5+Math.sin(wy*.0021)*145+Math.sin(wy*.006)*26;const onPath=Math.abs(wx+32-pathX)<54||Math.abs(wy+32-(H*.48+Math.sin(wx*.002)*45))<19;let pond=((wx+32-2200)/245)**2+((wy+32-1530)/155)**2<1||((wx+32-750)/130)**2+((wy+32-470)/105)**2<1;ctx.fillStyle=pond?'#253a36':onPath?'#554c3b':colors[Math.floor(s*colors.length)];ctx.fillRect(sx,sy,TILE+1,TILE+1);if(pond){ctx.fillStyle='#36504a';ctx.globalAlpha=.2;ctx.fillRect(sx,sy,TILE,TILE);ctx.globalAlpha=1;}if(onPath&&!pond){ctx.fillStyle=`rgba(190,166,112,${.025+s*.045})`;ctx.fillRect(sx,sy,TILE,TILE);}if(!pond&&s>.25&&s<.32){ctx.fillStyle='#a1a077';ctx.globalAlpha=.18;ctx.beginPath();ctx.ellipse(sx+18+s*25,sy+22,TILE*.12,TILE*.05,s,0,7);ctx.fill();ctx.globalAlpha=1;}if(s>.94&&!pond){ctx.fillStyle='#c8ad76';ctx.globalAlpha=.26;ctx.fillRect(sx+12+s*20,sy+11,2,2);ctx.fillRect(sx+42,sy+44,2,2);ctx.globalAlpha=1;}}
    // marsh pools and misty water sheen
    for(const p of [{x:2200,y:1530,rx:245,ry:155},{x:750,y:470,rx:130,ry:105}]){const s=worldToScreen(p.x,p.y);ctx.fillStyle='#233a35';ctx.beginPath();ctx.ellipse(s.x,s.y,p.rx,p.ry,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#68766655';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(s.x,s.y,p.rx+3,p.ry+3,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#98a58a22';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(s.x-18,s.y-4,p.rx*.72,p.ry*.67,-.05,0,Math.PI*2);ctx.stroke();}
  }
  function drawTree(x,y,scale=1){const s=worldToScreen(x,y),size=scale;ctx.save();ctx.translate(s.x,s.y);ctx.scale(size,size);ctx.fillStyle='#060b08aa';ctx.beginPath();ctx.ellipse(4,10,26,12,0,0,7);ctx.fill();ctx.fillStyle='#28251c';ctx.beginPath();ctx.ellipse(0,2,7,10,0,0,7);ctx.fill();for(const b of [[-12,-9,17,'#243026'],[8,-13,18,'#35402d'],[-2,-21,16,'#303a2a'],[17,1,13,'#293527'],[-18,3,14,'#202a23']]){ctx.fillStyle=b[3];ctx.beginPath();ctx.arc(b[0],b[1],b[2],0,7);ctx.fill();ctx.fillStyle='#66704b55';ctx.beginPath();ctx.arc(b[0]-4,b[1]-5,b[2]*.55,0,7);ctx.fill();}ctx.restore();}
  function drawRuin(x,y){const s=worldToScreen(x,y);ctx.save();ctx.translate(s.x,s.y);ctx.fillStyle='#0a0c09aa';ctx.beginPath();ctx.ellipse(0,25,100,27,0,0,7);ctx.fill();ctx.fillStyle='#4b4a3e';ctx.fillRect(-75,-7,150,26);ctx.fillStyle='#696350';ctx.fillRect(-70,-12,140,10);ctx.fillStyle='#282d27';ctx.fillRect(-48,-4,27,21);ctx.fillRect(21,-4,28,21);ctx.fillStyle='#151a16';ctx.fillRect(-40,-2,13,20);ctx.fillRect(28,-2,13,20);ctx.fillStyle='#625e4d';ctx.fillRect(-93,3,24,16);ctx.fillRect(68,4,26,15);ctx.fillStyle='#847857';ctx.fillRect(-86,0,9,4);ctx.fillRect(72,1,10,4);ctx.restore();}
  function drawActor(actor,isPlayer=false){const s=worldToScreen(actor.x,actor.y),phase=elapsed*3+(actor.phase||0),bob=isPlayer&&keys.size?Math.sin(phase*3)*1.8:Math.sin(phase)*1.2;ctx.save();ctx.translate(s.x,s.y+bob);ctx.fillStyle='#060908a8';ctx.beginPath();ctx.ellipse(0,10,15,7,0,0,7);ctx.fill();if(!isPlayer){const glow=ctx.createRadialGradient(0,0,2,0,0,30);glow.addColorStop(0,'#a6413c70');glow.addColorStop(1,'#a6413c00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,30,0,7);ctx.fill();ctx.globalAlpha=.48+Math.sin(phase*1.6)*.12;ctx.fillStyle='#89948c';ctx.beginPath();ctx.moveTo(-13,2);ctx.quadraticCurveTo(-17,-18,-3,-22);ctx.quadraticCurveTo(8,-27,13,-8);ctx.lineTo(17,9);ctx.quadraticCurveTo(5,2,0,15);ctx.quadraticCurveTo(-5,9,-14,14);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#c7c1aa';ctx.beginPath();ctx.arc(0,-10,8,0,7);ctx.fill();ctx.fillStyle='#211c1a';ctx.beginPath();ctx.ellipse(0,-12,7,4,0,0,7);ctx.fill();ctx.fillStyle='#ee6e53';ctx.shadowColor='#fb5a43';ctx.shadowBlur=8;ctx.fillRect(-4,-10,2,1.8);ctx.fillRect(3,-10,2,1.8);ctx.shadowBlur=0;}
    else{if(player.invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#33362f';ctx.beginPath();ctx.moveTo(-11,1);ctx.lineTo(-8,-11);ctx.lineTo(0,-17);ctx.lineTo(9,-10);ctx.lineTo(12,2);ctx.lineTo(7,11);ctx.lineTo(-7,11);ctx.closePath();ctx.fill();ctx.fillStyle='#6b282b';ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(-7,-8);ctx.lineTo(0,-14);ctx.lineTo(8,-8);ctx.lineTo(11,10);ctx.lineTo(0,7);ctx.lineTo(-10,11);ctx.closePath();ctx.fill();ctx.fillStyle='#252a26';ctx.beginPath();ctx.arc(0,-11,7,0,7);ctx.fill();ctx.fillStyle='#121815';ctx.beginPath();ctx.ellipse(0,-12,7,4,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#d5bc83';ctx.fillRect(2,-11,2,1.6);const a=player.attack>0?player.facing:player.facing;ctx.save();ctx.rotate(a);ctx.strokeStyle='#c9c4b1';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(6,-2);ctx.lineTo(18,-8);ctx.stroke();ctx.strokeStyle='#a88454';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(5,-2);ctx.lineTo(10,-4);ctx.stroke();ctx.restore();ctx.globalAlpha=1;}
    ctx.restore();if(!isPlayer&&selected===actor&&actor.alive){ctx.strokeStyle='#d9bb7966';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(s.x,s.y+9,17,6,0,0,7);ctx.stroke();}}
